package local.mediacenter.library
import org.json.*
import org.junit.Test
import org.junit.Assert.*
class OfflineRulesPlanTest {
 private fun row()=JSONObject().put("id","rule").put("account","account").put("kind","album").put("item","album").put("title","Saved album").put("enabled",true).put("unmetered",true).put("limit",2)
 @Test fun checksAreHourlyAndDefinitionChangesInvalidateCheckpoint(){val rule=OfflineRulesPlan.parse(row());val status=JSONObject().put("fingerprint",rule.fingerprint()).put("lastChecked",7200000);assertFalse(OfflineRulesPlan.due(rule,status,7200001));assertTrue(OfflineRulesPlan.due(rule,status,10800000));assertTrue(OfflineRulesPlan.due(rule.copy(item="another"),status,7200001));assertFalse(OfflineRulesPlan.due(rule.copy(enabled=false),status,10800000))}
 @Test fun clockRollbackDoesNotBlockChecksForever(){val rule=OfflineRulesPlan.parse(row());assertTrue(OfflineRulesPlan.due(rule,JSONObject().put("fingerprint",rule.fingerprint()).put("lastChecked",9000000),8000000))}
 @Test fun legacyCheckpointIsRespectedUntilDefinitionHasNativeCheckpoint(){val rule=OfflineRulesPlan.parse(row().put("lastRun",7200000));assertFalse(OfflineRulesPlan.due(rule,null,7200001));assertTrue(OfflineRulesPlan.due(rule,null,10800000))}
 @Test fun savedOnlyAndLimitKeepOrderAndAvoidDuplicates(){val rule=OfflineRulesPlan.parse(row());val tracks=JSONArray().put(JSONObject().put("id","online")).put(JSONObject().put("id","first").put("saved",true)).put(JSONObject().put("id","first").put("saved",true)).put(JSONObject().put("id","second").put("saved",true)).put(JSONObject().put("id","third").put("saved",true));val raw=JSONObject().put("album",JSONObject().put("song",tracks));assertEquals(listOf("first","second"),OfflineRulesPlan.ids(raw,rule,true));assertEquals(listOf("online","first"),OfflineRulesPlan.ids(raw,rule,false))}
 @Test fun podcastOrUnboundedAndDuplicateRulesFailExplicitly(){for(bad in listOf(row().put("kind","podcast"),row().put("limit",501),row().put("enabled","true"),row().put("item",""))){assertTrue(runCatching{OfflineRulesPlan.parse(bad)}.isFailure)};assertTrue(runCatching{OfflineRulesPlan.definitions(JSONObject().put("offlineRules",JSONArray().put(row()).put(row())))}.isFailure);assertTrue(runCatching{OfflineRulesPlan.definitions(JSONObject().put("offlineRules",JSONArray((0..100).map{row().put("id",it.toString())})))}.isFailure)}
 @Test fun playlistAndFavoritesUseTheirExplicitMusicModels(){val playlist=OfflineRulesPlan.parse(row().put("kind","playlist"));assertEquals("getPlaylist",OfflineRulesPlan.method(playlist));assertEquals(listOf("a"),OfflineRulesPlan.ids(JSONObject().put("playlist",JSONObject().put("entry",JSONArray().put(JSONObject().put("id","a")))),playlist,false));val favorites=OfflineRulesPlan.parse(row().put("kind","favorites").put("item",""));assertEquals("getStarred2",OfflineRulesPlan.method(favorites));assertTrue(OfflineRulesPlan.ids(JSONObject().put("starred2",JSONObject()),favorites,false).isEmpty())}
}
